async function action(name,id){
  state.error='';
  const d=state.data, tk=state.detail?.value;
  if(name==='logout'){state.token=null;state.user=null;state.detail=null;state.page='dashboard';clearSession();return boot()}
  if(name==='back'){state.detail=null;return render()}
  if(ops.ACTIONS.includes(name))return ops.action(name,id);
  if(name==='ticket'||name==='equipment')return loadDetail(name,id).then(v=>{state.detail={type:name,value:v};render();window.scrollTo(0,0)}).catch(fail);
  if(name==='done'||name==='undo')return api('/checklist/'+id,'PATCH',{done:name==='done'}).then(()=>refresh()).catch(fail);
  if(name==='visitDone')return save('/visits/'+id,'PATCH',{status:'completed'},'Visit completed').catch(fail);
  if(name==='approveProvider'){const p=d.providers.find(x=>x.id===id); if (p.approved&&!await confirmAction(`Suspend ${p.name}?`,'They can no longer be assigned new work. Work already assigned is not affected.',{confirmLabel:'Suspend'})) return; return save(`/providers/${id}/approval`,'PATCH',{approved:!p.approved},p.approved?'Provider suspended':'Provider approved').catch(fail)}
  if(name==='userActive'){const x=d.users.find(u=>u.id===id); if (x.active&&!await confirmAction(`Deactivate ${x.name}?`,'They are signed out immediately and cannot sign in. Their history is kept, and you can reactivate them later.',{confirmLabel:'Deactivate'})) return; return save('/users/'+id,'PATCH',{active:!x.active},x.active?'User deactivated':'User reactivated').catch(fail)}
  if(name==='deviceActive'){const x=d.devices.find(v=>v.id===id); if (x.active&&!await confirmAction(`Deactivate device ${x.external_device_id}?`,'Readings from this device will be rejected until it is activated again.',{confirmLabel:'Deactivate'})) return; return save('/devices/'+id,'PATCH',{active:!x.active},'Device updated').catch(fail)}
  if(name==='runSync')return api('/integrations/sync','POST',{}).then(r=>{toast(`Sync ${r.status}: ${r.accepted} accepted, ${r.duplicates} duplicate, ${r.rejected} rejected`);return refresh()}).catch(fail);
  if(name.startsWith('fulfil:')){const p=d.parts.find(x=>x.id===id), stage=name.slice(7), needsRef=stage!=='fulfilled';return openDialog(`${label('status',stage)}: ${p.item}`,`<div class="form-grid">${field('reference',stage==='ordered'?'Purchase order number':stage==='shipped'?'Tracking number or delivery note':'Delivery reference',{value:stage==='ordered'?'':p.fulfilment_reference,required:needsRef,wide:true})}</div>`,{onSubmit:async fd=>{await save(`/parts/${id}/fulfilment`,'POST',{status:stage,reference:fd.get('reference')},`Marked ${label('status',stage).toLowerCase()}`)}})}
  if(name==='quotes')return api(`/parts/${id}/quotes`).then(q=>{const p=d.parts.find(x=>x.id===id),canDecide=is('customer_admin','plant_manager');openDialog(`${t('action.viewQuotes')}: ${p.item}`,q.length?q.map(x=>{const expired=x.valid_until&&Date.parse(x.valid_until)+86400000<=Date.now();return `<div class="quote-row"><div><b>${formatMoney(x.amount_minor,x.currency)}</b> <span class="muted">· ${x.lead_days} ${t('label.days')} lead time · issued ${formatDate(x.created_at)}${x.valid_until?` · valid to ${formatDate(x.valid_until)}`:''}</span></div><div class="row">${pill('status',x.status)}${expired&&x.status==='pending'?'<span class="pill critical">⚠ Expired</span>':''}${canDecide&&x.status==='pending'&&!expired?btn(t('action.approve'),'decide:approved','primary small',x.id)+btn(t('action.reject'),'decide:rejected','secondary small',x.id):''}</div></div>`}).join(''):`<p class="muted">${t('msg.noRecords')}</p>`,{onOpen:dlg=>dlg.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id))})}).catch(fail);
  if(name.startsWith('decide:')){const decision=name.slice(7); if (decision==='rejected'&&!await confirmAction('Reject this quotation?','The request goes back to the service team for a new quote.',{confirmLabel:'Reject quote'})) return; closeDialog(); return save(`/quotes/${id}/decision`,'POST',{decision},decision==='approved'?'Quote approved':'Quote rejected').catch(fail)}
  if(name==='writeGuide'){const id0=tk.id;toast(tk.guideData?.aiEnabled?'Writing the guide with AI. This can take up to a minute.':'Updating the guide');return api(`/tickets/${id0}/guide`,'POST',{}).then(r=>{if(state.detail?.value?.id===id0){state.detail.value.guideData=r;render()}toast('Guide ready')}).catch(fail)}
  if(name==='vrGuide')return openVr(tk).catch(fail);
  if(name==='uploadImage'){const e=state.detail.value;return openDialog(`Picture: ${e.asset_tag||e.model}`,`<div class="form-grid"><div class="fld wide"><label for="f-image">Photo of the machine (JPEG, PNG or WebP, max 5 MB) <span class="req">*</span></label><input id="f-image" name="file" type="file" accept="image/jpeg,image/png,image/webp" required></div></div>`,{submitLabel:'Upload',onSubmit:async fd=>{const file=fd.get('file');if(file.size>5*1024*1024)throw Error('Picture exceeds 5 MB');await api(`/equipment/${e.id}/image`,'POST',{filename:file.name,mime:file.type,base64:await fileBase64(file)});toast('Picture saved');await refresh()}})}
  if(name==='removeImage'){if(!await confirmAction('Remove the picture?','The machine shows its type icon instead. You can upload a new picture at any time.',{confirmLabel:'Remove'}))return;return api(`/equipment/${state.detail.value.id}/image`,'DELETE').then(()=>{toast('Picture removed');return refresh()}).catch(fail)}
  if(name==='newTicket')return ticketForm();
  if(name==='ackAlert')return save(`/alerts/${id}/acknowledge`,'POST',{},'Alert acknowledged').catch(fail);
  if(name==='resolveAlert')return save(`/alerts/${id}/resolve`,'POST',{},'Alert resolved').catch(fail);
  if(name==='alertTicket'){const a=d.alerts.find(x=>x.id===id);return ticketForm(a.equipment_id,a)}
  if(name==='oeeFor'){state.oeeFilter={range:'7d',plantId:'',equipmentId:id};state.oee=undefined;state.page='oee';state.detail=null;return render()}
  if(name==='newProduct')return productForm();
  if(name==='trend'){const [eq,param]=id.split('|');return trendDialog(eq,param).catch(fail)}
  if(name==='limits')return limitsForm(id).catch(fail);
  if(name==='editProduct')return productForm(d.products.find(x=>x.id===id));
  if(name==='editShifts')return shiftsForm(d.plants.find(x=>x.id===id)).catch(fail);
  if(name==='newTicketHere')return ticketForm(state.detail.value.id);
  if(name==='newEquipment')return equipmentForm();
  if(name==='editEquipment')return equipmentForm(state.detail.value);
  if(name==='newContract')return contractForm();
  if(name==='addVisit'){const c=d.contracts.find(x=>x.id===id);return openDialog(`${t('action.addVisit')}: ${c.contract_number||c.title}`,`<div class="form-grid">${select('equipmentId',t('label.asset'),c.equipmentIds.map(e=>[e,assetName(e)]),{required:true})}${field('dueAt','Date and time (plant local time)',{type:'datetime-local',required:true})}${field('notes','Scope of visit',{wide:true})}</div>`,{onSubmit:async fd=>{await save(`/contracts/${id}/visits`,'POST',Object.fromEntries(fd),'Visit scheduled')}})}
  if(name==='renewal')return renewalForm(d.contracts.find(x=>x.id===id));
  if(name==='newCompany')return companyForm();
  if(name==='editCompany')return companyForm(d.companies.find(x=>x.id===id));
  if(name==='newPlant')return plantForm();
  if(name==='editPlant')return plantForm(d.plants.find(x=>x.id===id));
  if(name==='newUser')return userForm();
  if(name==='newProvider')return providerForm();
  if(name==='editProvider')return providerForm(d.providers.find(x=>x.id===id));
  if(name==='resetPassword'){const x=d.users.find(v=>v.id===id);return openDialog(`${t('action.resetPassword')}: ${x.name}`,`<div class="form-grid">${field('newPassword','New temporary password',{required:true,minlength:12,autocomplete:'off',wide:true,help:`${x.name} is signed out on all devices and must choose a new password at next sign-in. Give them this password privately.`})}</div>`,{submitLabel:'Reset password',onSubmit:async fd=>{await save(`/users/${id}/password`,'POST',{newPassword:fd.get('newPassword')},t('msg.passwordReset'))}})}
  if(name==='newArea')return openDialog('Add service area',`<div class="form-grid">${field('code','Code',{required:true,maxlength:20,help:'Short and stable, e.g. IN-SOUTH',autocapitalize:'characters'})}${field('name','Name',{required:true,help:'e.g. India – South'})}</div>`,{onSubmit:async fd=>{await save('/service-areas','POST',Object.fromEntries(fd),'Service area added')}});
  if(name==='renameArea'){const a=d.serviceAreas.find(x=>x.code===id);return openDialog(`Rename ${a.code}`,`<div class="form-grid">${field('name','Name',{value:a.name,required:true,wide:true,help:'The code stays the same so existing plants and engineers keep matching.'})}</div>`,{onSubmit:async fd=>{await save(`/service-areas/${encodeURIComponent(a.code)}`,'PATCH',{name:fd.get('name')},'Service area renamed')}})}
  if(name==='addCode'){const title={failureCategories:'Failure categories',failureModes:'Failure modes',rootCauses:'Root causes',actions:'Maintenance actions'}[id];return openDialog(`Add to ${title}`,`<div class="form-grid">${field('label','Name',{required:true,maxlength:60,wide:true,help:'e.g. Lubrication. It is offered when breakdowns are reported or closed from now on.'})}</div>`,{submitLabel:'Add',onSubmit:async fd=>{const r=await api(`/settings/codes/${id}`,'POST',{label:fd.get('label')});state.cat=null;toast(`Added "${humanise(r.code)}"`);await refresh()}})}
  if(name==='deleteCode'){const [list,code]=id.split('|');if(!await confirmAction(`Delete "${humanise(code)}"?`,'It is no longer offered when breakdowns are reported or closed. Tickets that already use it keep it.',{confirmLabel:'Delete'}))return;return api(`/settings/codes/${list}/${encodeURIComponent(code)}`,'DELETE').then(async r=>{state.cat=null;toast(r.ticketsKeepingCode?`Deleted. ${r.ticketsKeepingCode} ticket(s) keep this code.`:'Deleted');await refresh()}).catch(fail)}
  if(name==='editChecklist')return openDialog(`Standard checklist: ${label('machine',id)}`,`<div class="form-grid">${field('items','Checklist items',{type:'textarea',value:(d.checklists[id]||[]).join('\n'),required:true,wide:true,rows:12,help:'One item per line, in the order engineers should work through them. Applies to jobs accepted from now on.'})}</div>`,{onSubmit:async fd=>{await save(`/settings/checklists/${id}`,'PATCH',{items:String(fd.get('items')).split('\n').map(s=>s.trim()).filter(Boolean)},'Checklist saved')}});
  if(name==='status')return statusForm(tk);
  if(name==='assign')return api(`/tickets/${tk.id}/candidates`).then(list=>{const ok=list.filter(c=>c.eligible),no=list.filter(c=>!c.eligible);openDialog(t('action.assign'),`<div class="form-grid">${ok.length?select('assignee','Engineer or provider',ok.map(c=>[`${c.type}:${c.id}`,`${c.type==='engineer'?'Engineer':'Provider'}: ${c.name} · ${c.openWork} open jobs`]),{required:true,wide:true,help:'Only those covering this plant\'s service area with the right machine skill are listed'}):'<p class="wide notice error">No eligible engineer or provider. Check service areas and skills.</p>'}${no.length?`<div class="wide mini">Not eligible: ${no.map(c=>`${esc(c.name)} (${esc(c.reasons.join(', '))})`).join('; ')}</div>`:''}</div>`,{submitLabel:'Assign',onSubmit:ok.length?async fd=>{const [assigneeType,assigneeId]=String(fd.get('assignee')).split(':');await save(`/tickets/${tk.id}/assign`,'POST',{assigneeType,assigneeId},'Assigned')}:undefined})}).catch(fail);
  if(name==='checklist')return openDialog(t('action.checklist'),`<div class="form-grid">${field('item','Inspection item',{required:true,wide:true})}${field('note',t('label.note'),{wide:true})}</div>`,{onSubmit:async fd=>{await save(`/tickets/${tk.id}/checklist`,'POST',Object.fromEntries(fd))}});
  if(name==='workLog')return openDialog(t('action.logWork'),`<div class="form-grid">${field('description','Work performed',{type:'textarea',required:true,wide:true})}${field('minutes','Time spent',{type:'number',required:true,unit:'min',min:1,max:10080})}${field('partsUsed','Parts used',{help:'Part numbers and quantities'})}</div>`,{onSubmit:async fd=>{const v=Object.fromEntries(fd);await save(`/tickets/${tk.id}/work-logs`,'POST',{...v,minutes:Number(v.minutes)},'Work logged')}});
  if(name==='part')return openDialog(t('action.requestPart'),`<div class="form-grid">${field('partNumber','Part number',{required:true,help:'Manufacturer or catalogue number'})}${field('manufacturer','Manufacturer')}${field('item','Description',{required:true,wide:true})}${field('quantity','Quantity',{type:'number',value:1,required:true,min:1})}${select('unit','Unit',options(state.cat?.partUnits||[]),{value:'pcs',required:true})}${select('urgency','Urgency',options(state.cat?.partUrgency||[]),{value:'normal',required:true,help:'Breakdown: machine is stopped waiting for this part'})}</div>`,{onSubmit:async fd=>{const v=Object.fromEntries(fd);await save(`/tickets/${tk.id}/parts`,'POST',{...v,quantity:Number(v.quantity)},'Part requested')}});
  if(name==='signoff'){if(customer())return openDialog(t('action.signoff'),`<div class="form-grid">${field('signerName',t('label.signerName'),{value:state.user.name,required:true,wide:true})}</div>`,{submitLabel:'Sign off',onSubmit:async fd=>{await save(`/tickets/${tk.id}/signoff`,'POST',{signerName:fd.get('signerName')},'Signed off')}});
    let pad;return openDialog(t('action.signoff'),`<div class="form-grid">${field('signerName',t('label.signerName'),{required:true,wide:true})}<div class="wide"><label>${t('label.signature')} <span class="req">*</span></label><canvas class="signature" id="sig"></canvas><button type="button" class="secondary small" id="clear-sig">${t('action.clear')}</button></div></div>`,{submitLabel:'Sign off',onOpen:dlg=>{pad=signaturePad(dlg.querySelector('#sig'));dlg.querySelector('#clear-sig').onclick=()=>pad.clear()},onSubmit:async fd=>{if(pad.isEmpty())throw Error(t('msg.signFirst'));await save(`/tickets/${tk.id}/signoff`,'POST',{signerName:fd.get('signerName'),signatureBase64:pad.toBase64()},'Signed off')}})}
  if(name==='quote'){const p=d.parts.find(x=>x.id===id),code=companyOf(p.company_id)?.currency||prefs().currency;return openDialog(`${t('action.quote')}: ${p.item}`,`<div class="form-grid">${field('amount','Total price',{type:'number',required:true,min:0.01,step:0.01,unit:code})}${select('currency','Currency',currencies().map(x=>[x,x]),{value:code,required:true})}${field('leadDays','Lead time',{type:'number',value:3,required:true,unit:'days',min:0,max:365})}${field('validUntil','Quote valid until',{type:'date',value:today(30),required:true,min:today()})}</div>`,{submitLabel:'Send quote',onSubmit:async fd=>{const v=Object.fromEntries(fd);await save(`/parts/${id}/quote`,'POST',{amountMinor:toMinorUnits(v.amount,v.currency),currency:v.currency,leadDays:Number(v.leadDays),validUntil:v.validUntil},'Quote sent')}})}
  if(name==='attachment')return openDialog(t('action.attach'),`<div class="form-grid">${select('kind','Type',(state.detail.type==='equipment'?['manual','photo']:['photo','evidence']).map(x=>[x,humanise(x)]),{required:true})}<div class="fld wide"><label for="f-file">PDF or image (max 5 MB) <span class="req">*</span></label><input id="f-file" name="file" type="file" accept=".pdf,image/png,image/jpeg,image/webp" required></div></div>`,{submitLabel:'Upload',onSubmit:async fd=>{const file=fd.get('file');if(file.size>5*1024*1024)throw Error('File exceeds 5 MB');await save('/attachments','POST',{entityType:state.detail.type,entityId:state.detail.value.id,kind:fd.get('kind'),filename:file.name,mime:file.type,base64:await fileBase64(file)},'File uploaded')}});
  if(name==='mapDevice')return openDialog('Map IoT device to this asset',`<div class="form-grid">${field('externalDeviceId','External device ID',{required:true,help:'As used by the machine-data API'})}${field('staleAfterMinutes','Mark stale after',{type:'number',value:30,unit:'min',min:1,max:10080,required:true})}</div>`,{onSubmit:async fd=>{await save('/devices','POST',{externalDeviceId:fd.get('externalDeviceId'),equipmentId:state.detail.value.id,staleAfterMinutes:Number(fd.get('staleAfterMinutes'))},'Device mapped')}});
}
// Forms that live on a page rather than in a dialog (account password, default response targets).
function bindInlineForms(){
  document.querySelectorAll('form[data-inline]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));try{
    if(f.dataset.inline==='password'){const r=await api('/me/password','POST',v);saveSession(r.token);state.token=r.token;state.user=r.user;f.reset();toast(t('msg.passwordChanged'));render();}
    if(f.dataset.inline==='scan'){const r=await api('/settings/scan-policy','PATCH',v);if(state.cat)state.cat.scanPolicy=r;toast('Scan policy saved');render();}
    if(f.dataset.inline==='targets'){await save('/settings/response-targets','PATCH',Object.fromEntries(Object.entries(v).map(([k,x])=>[k,Number(x)])),'Response targets saved');}
  }catch(err){toast(err.message,'error')}});
}
// A ticket's detail also carries its assistant conversation and repair guide.
async function loadDetail(type,id){ if (type==='equipment') return api('/equipment/'+id); const [t,assistantData,guideData]=await Promise.all([api('/tickets/'+id),api(`/tickets/${id}/assistant`).catch(()=>null),api(`/tickets/${id}/guide`).catch(()=>null)]); return {...t,assistantData,guideData}; }
async function refresh(){if(state.detail)state.detail.value=await loadDetail(state.detail.type,state.detail.value.id).catch(()=>{state.detail=null});await load();}
const fileBase64=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});
document.addEventListener('click',async e=>{const a=e.target.closest('[data-download]');if(!a)return;e.preventDefault();try{const r=await fetch(a.href,{headers:{authorization:`Bearer ${state.token}`}});if(!r.ok)throw Error('Unable to download');const url=URL.createObjectURL(await r.blob()),link=document.createElement('a');link.href=url;link.download=a.textContent;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(err){toast(err.message,'error')}});
const ops=createOps({state,api,save,render,fail,when,assetName,header,RANGES,pctText,since,factoryManager,admin,is,customer,t,refresh,action});
boot();
